effect.shader:
const float PI = 3.14159265;

vec3 girarY(vec3 v, float a) {
    float c = cos(a);
    float s = sin(a);
    return vec3(v.x * c + v.z * s, v.y, -v.x * s + v.z * c);
}

vec3 girarX(vec3 v, float a) {
    float c = cos(a);
    float s = sin(a);
    return vec3(v.x, v.y * c - v.z * s, v.y * s + v.z * c);
}

/** Latitude e longitude viram coordenada de textura equirretangular. */
vec2 paraEquirretangular(vec3 dir) {
    float u = atan(dir.z, dir.x) / (2.0 * PI) + 0.5;
    float v = acos(clamp(dir.y, -1.0, 1.0)) / PI;
    return vec2(u, v);
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    float volta = (spin / 360.0 + acTime * autoSpin) * 2.0 * PI;
    float inclinacao = tilt * PI / 180.0;

    if (mode == 1) {
        // ----------------------------------------------------- ver de dentro
        //
        // A câmera está no centro da esfera e olha para fora. O raio é montado
        // a partir do campo de visão, e a direção dele já é a coordenada.
        vec2 tela = (acScreenNorm - 0.5) * vec2(acAspect, 1.0) * 2.0;
        float f = tan(fov * PI / 360.0);
        vec3 raio = normalize(vec3(tela.x * f, -tela.y * f, 1.0));
        raio = girarX(raio, inclinacao);
        raio = girarY(raio, volta);

        fragColor = texture(inputImg, paraEquirretangular(raio));
        return;
    }

    // --------------------------------------------------- enrolar na esfera
    vec2 p = (acScreenNorm - center) * vec2(acAspect, 1.0);
    float d = length(p) / max(radius, 1e-4);

    if (d > 1.0) {
        // Fora da bola: ou fica a camada, ou fica nada.
        fragColor = keepLayer ? original : vec4(original.rgb, 0.0);
        return;
    }

    // O ponto da esfera que este pixel enxerga. `z` sai de x²+y²+z²=1 — é a
    // interseção do raio com a esfera, resolvida de cabeça.
    vec3 ponto = vec3(p / max(radius, 1e-4), sqrt(max(1.0 - d * d, 0.0)));

    vec3 naEsfera = girarX(ponto, inclinacao);
    naEsfera = girarY(naEsfera, volta);

    vec2 uv = paraEquirretangular(normalize(naEsfera));
    vec3 cor = texture(inputImg, uv).rgb;

    // O sombreamento é o que faz o círculo virar bola. `ponto` já é a normal da
    // superfície: numa esfera de raio 1 centrada na origem, as duas são a mesma
    // coisa — e isso economiza a conta inteira.
    float ang = lightAngle * PI / 180.0;
    vec3 luz = normalize(vec3(cos(ang), -sin(ang), 0.75));
    float difuso = max(dot(ponto, luz), 0.0);
    cor *= mix(1.0, 0.25 + 0.75 * difuso, shading);

    // Luz de contorno: a borda da esfera acende, como todo objeto redondo
    // iluminado por trás. É o detalhe que descola a bola do fundo.
    float contorno = pow(1.0 - ponto.z, 3.0) * rim;
    cor += contorno;

    // Uma borda suave de um pixel e meio, senão a bola sai serrilhada.
    float suave = 1.0 - smoothstep(1.0 - 1.5 / max(acResolution.y * radius, 1.0), 1.0, d);
    float alfa = suave;

    if (keepLayer) {
        float saidaAlfa = alfa + original.a * (1.0 - alfa);
        vec3 saidaCor = saidaAlfa > 0.0
            ? (cor * alfa + original.rgb * original.a * (1.0 - alfa)) / saidaAlfa
            : vec3(0.0);
        fragColor = vec4(saidaCor, saidaAlfa);
    } else {
        fragColor = vec4(cor, alfa);
    }
}
